Longest Equal Subarray with at Most K IncrementsLongest Equal Subarray with at Most K IncrementsGiven an array arr[] and an integer k, find the maximum length subarray whose elements can be made equal using at most k increments. An element can be incremented multiple times, but the total number of increments must not exceed k.Examples:Input: arr[] = [2, 4, 8, 5, 9, 6], k = 6Output: 3Explanation: Subarray [8, 5, 9] can be changed to [9, 9, 9] with 5 increments, which is within the limit k = 6.Input: arr[] = [2, 2, 4], k = 10Output: 3Explanation: Entire array can be made [4, 4, 4] using 4 increments, well within the allowed k = 10.Input: arr[] = [1, 2, 3, 4], k = 2Output: 2Explanation: Subarrays [1, 2], [2, 3], and [3, 4] can each be converted into equal elements using 1 increment.Table of Content[Naive Approach] Generate and Check All Subarrays - O(n^3) Time and O(1) Space[Expected Approach] Sliding Window with Deque - O(n) Time and O(n) Space[Naive Approach] Generate and Check All Subarrays - O(n^3) Time and O(1) SpaceGenerate all possible subarrays and  for each subarray, find its maximum element as the target and calculate the total increments required. If the required increments do not exceed k, update the maximum length.Initialize maxLength as 1 to store the answer.Use two loops to generate all subarrays [i...j].For each subarray, find its max element as the target.Compute total increments needed to match this target.If increments ≤ k, update maxLength.Return the final max length.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Calculate increments to make subarray equal to target
int getIncrements(vector<int>& arr, int left, int right, int target) {
    int total = 0;
    for (int i = left; i <= right; i++) {
        if (arr[i] < target) {
            total += target - arr[i];
        }
    }
    return total;
}

// Find maximum element in subarray
int getMax(vector<int>& arr, int left, int right) {
    int maxValue = arr[left];
    for (int i = left + 1; i <= right; i++) {
        maxValue = max(maxValue, arr[i]);
    }
    return maxValue;
}

// Return maximum valid subarray length
int maxEqualSubarrayLength(vector<int>& arr, int k) {
    int n = arr.size();
    int maxLength = 1;

    // Try all possible subarrays
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {

            // Find max element in current subarray manually
            int maxElem = getMax(arr, i, j);

            // Calculate how many increments are needed
            int increments = getIncrements(arr, i, j, maxElem);

            // Check if it's within allowed limit
            if (increments <= k) {
                maxLength = max(maxLength, j - i + 1);
            }
        }
    }

    return maxLength;
}

int main() {
    vector<int> arr = {2, 4, 8, 5, 9, 6};
    int k = 6;

    cout << maxEqualSubarrayLength(arr, k) << endl;
    return 0;
}


