[Expected Approach] Sliding Window with Deque - O(n) Time and O(n) SpaceThe idea is based on the fact that if we maintain sum of elements and max in a window, then we can count the number of increments in O(1) time using  maxElement * windowSize - windowSum. So we maintain a sliding window with these parameters. To track the maximum of every window size, we use a monotonic (decreasing order) deque.Use two pointers (left, right) to maintain a sliding window and keep track of the sum.Maintain a monotonic decreasing deque to get the maximum element.Compute cost = maxElement * window_size - sum.If cost exceeds k, shrink the window from the left and update the deque.Track and return the maximum valid window length.
            C++

    #include <iostream>
#include <vector>
#include <deque>
using namespace std;

int maxEqualSubarrayLength(vector<int>& arr, int k) {
    int left = 0, maxLength = 0;
    long long sum = 0;

    deque<int> dq;

    for (int right = 0; right < arr.size(); right++) {
        sum += arr[right];

        // Maintain decreasing deque
        while (!dq.empty() && dq.back() < arr[right]) {
            dq.pop_back();
        }
        dq.push_back(arr[right]);

        // Shrink window if cost > k
        while ((long long)dq.front() * (right - left + 1) - sum > k) {
            sum -= arr[left];

            if (arr[left] == dq.front()) {
                dq.pop_front();
            }
            left++;
        }

        maxLength = max(maxLength, right - left + 1);
    }

    return maxLength;
}

int main() {
    vector<int> arr = {2, 4, 8, 5, 9, 6};
    int k = 6;

    cout << maxEqualSubarrayLength(arr, k) << endl;
    return 0;
}


